import { getMessaging, getToken, onMessage } from 'firebase/messaging';
import { db } from '../firebase';
import { ref, set } from 'firebase/database';

const VAPID_KEY = 'BGdcfaL37a8w6EDc55GBH_nQLZ0w6zEEQzYnIX9yQiriXhsevuwmW3qYzoCIIUONC1-nViDEFCMjiPol4dQJj0k'; // Вставьте ваш ключ

// Запрос разрешения на уведомления
export const requestNotificationPermission = async () => {
  if (!('Notification' in window)) {
    console.log('This browser does not support notifications');
    return false;
  }

  const permission = await Notification.requestPermission();
  if (permission === 'granted') {
    console.log('Notification permission granted');
    return true;
  }
  return false;
};

// Ожидание активации сервис-воркера
const waitForServiceWorkerActivation = async (registration: ServiceWorkerRegistration) => {
  return new Promise<void>((resolve) => {
    if (registration.active) {
      resolve();
    } else {
      registration.addEventListener('activate', () => {
        resolve();
      });
    }
  });
};

// Регистрация сервис-воркера
export const registerServiceWorker = async () => {
  if ('serviceWorker' in navigator) {
    try {
      const swPath = `${process.env.PUBLIC_URL}/firebase-messaging-sw.js`;
      console.log('Registering service worker at:', swPath);
      
      const registration = await navigator.serviceWorker.register(swPath);
      console.log('Service Worker registered:', registration);
      
      // Ждем активации сервис-воркера
      await waitForServiceWorkerActivation(registration);
      console.log('Service Worker activated');
      
      return registration;
    } catch (error) {
      console.error('Service Worker registration failed:', error);
      return null;
    }
  }
  return null;
};

// Получение токена FCM
export const getFCMToken = async () => {
  try {
    // Сначала регистрируем и ждем активации сервис-воркера
    const registration = await registerServiceWorker();
    if (!registration) {
      console.error('No service worker registration');
      return null;
    }
    
    // Проверяем, что сервис-воркер активен
    if (!registration.active) {
      console.error('Service worker not active');
      return null;
    }
    
    const messaging = getMessaging();
    
    const token = await getToken(messaging, {
      vapidKey: VAPID_KEY,
      serviceWorkerRegistration: registration
    });
    
    if (token) {
      console.log('FCM Token:', token);
      const userId = localStorage.getItem('userId');
      if (userId) {
        await saveTokenToFirebase(userId, token);
      }
      return token;
    }
  } catch (error) {
    console.error('Error getting FCM token:', error);
  }
  return null;
};

// Сохранение токена в Firebase
const saveTokenToFirebase = async (userId: string, token: string) => {
  try {
    const tokenRef = ref(db, `users/${userId}/fcmTokens/${token}`);
    await set(tokenRef, true);
    console.log('Token saved to Firebase');
  } catch (error) {
    console.error('Error saving token:', error);
  }
};

// Прослушивание уведомлений в foreground
export const listenForMessages = () => {
  const messaging = getMessaging();
  
  onMessage(messaging, (payload) => {
    console.log('Message received in foreground:', payload);
    
    if (Notification.permission === 'granted') {
      const notificationTitle = payload.notification?.title || 'LinarApp';
      const notificationOptions = {
        body: payload.notification?.body || 'Новое сообщение',
        icon: '/linarapp/logo192.png',
        badge: '/linarapp/favicon.ico',
        vibrate: [200, 100, 200]
      };
      
      new Notification(notificationTitle, notificationOptions);
    }
  });
};

// Инициализация всех уведомлений
export const initNotifications = async () => {
  const hasPermission = await requestNotificationPermission();
  
  if (hasPermission) {
    // Ждем немного, чтобы сервис-воркер точно активировался
    await new Promise(resolve => setTimeout(resolve, 1000));
    
    const token = await getFCMToken();
    if (token) {
      console.log('FCM Token ready:', token);
      listenForMessages();
      return true;
    }
  }
  return false;
};